/**
 * The hair and makeup styles offered on the try-on page.
 *
 * Every id is a live YouCam template id — the provider only renders styles from
 * its own catalogue, so an invented id silently produces "no change".
 *
 * The head of each array is the set reviewed by eye for an Indian audience —
 * bridal gold, kajal, red lips, buns, braids and dark natural hair. Below that
 * marker sits the rest of the provider's catalogue, added wholesale and still
 * to be reviewed: it holds plenty that does not belong on this page (rainbow
 * and blonde dye jobs, glitter novelties, cheek stickers). Only the outright
 * costume categories — animal muzzles, national flags, Halloween, pride flags —
 * were left out.
 *
 * Note the provider's makeup catalogue is designed for women; the men's set is
 * its barest looks (even skin, groomed brows, next to no colour), so every
 * unreviewed makeup look is filed under Women.
 */
export interface TryOnStyle {
  id: string;
  title: string;
  gender: 'Women' | 'Men';
  thumb: string;
}

